    h, w = len(grid), len(grid[0])
    split = None
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and r == h // 2:
            split = ("row", r)
            break
    if split is None:
        for c in range(1, w - 1):
            if all(row[c] == grid[0][c] for row in grid) and c == w // 2:
                split = ("col", c)
                break
    if split is None:
        for r in range(h):
            if len(set(grid[r])) == 1 and r > 0 and h-r-1 == r:
                split = ("row", r)
                break
    if split is None:
        for c in range(w):
            if all(row[c] == grid[0][c] for row in grid) and c > 0 and w-c-1 == c:
                split = ("col", c)
                break
    if split is None:
        raise ValueError("separator not found")
    axis, k = split
    if axis == "row":
        a, b = grid[:k], grid[k+1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    fill = max(common, key=lambda v: sum(x == v for row in a for x in row) + sum(x == v for row in b for x in row))
    return [[3 if x == y else fill for x, y in zip(ar, br)] for ar, br in zip(a, b)]
'''
